(()=>{const n=document.querySelector("#country-input"),t=document.querySelector("#result-container");let e=null;function r(n){n.length>10?alert("Знайдено забагато збігів. Будь ласка, зробіть запит більш специфічним!"):n.length>=2&&n.length<=10?function(n){const e=`\n    <ul class="country-list">\n      ${n.map(n=>`<li>${n.name}</li>`).join("")}\n    </ul>\n  `;t.innerHTML=e}(n):1===n.length&&function(n){const e=n.languages.map(n=>n.name).join(", "),r=`\n    <div class="country-card">\n      <h2>${n.name}</h2>\n      <p><strong>Столиця:</strong> ${n.capital||"Немає"}</p>\n      <p><strong>Населення:</strong> ${n.population.toLocaleString()}</p>\n      <p><strong>Мови:</strong> ${e}</p>\n      <img src="${n.flag}" alt="Прапор ${n.name}" width="150">\n    </div>\n  `;t.innerHTML=r}(n[0])}n.addEventListener("input",n=>{const o=n.target.value.trim();clearTimeout(e),t.innerHTML="",o&&(e=setTimeout(()=>{var n;(n=o,fetch(`https://restcountries.com/v2/name/${n}`).then(n=>{if(!n.ok)throw new Error(n.statusText);return n.json()})).then(r).catch(()=>{alert("Країну не знайдено або виникла помилка запиту!")})},500))})})();